import os
import json
import re

def read_log_file(file_path):
    """
    Reads a log file and returns its content.
    Supports plain text and JSON formats.
    """
    if not os.path.exists(file_path):
        raise FileNotFoundError(f"Log file not found: {file_path}")

    _, ext = os.path.splitext(file_path)
    with open(file_path, 'r') as file:
        if ext.lower() == '.json':
            try:
                return json.load(file)
            except json.JSONDecodeError:
                raise ValueError(f"Invalid JSON format in file: {file_path}")
        else:
            return file.readlines()

def diagnose_faults(log_content):
    """
    Diagnoses faults based on log content.
    Supports both list of lines (plain text) and dict/list (JSON).
    Returns a summary report of detected faults.
    """
    fault_patterns = {
        r'error': 'General error detected',
        r'fail': 'Failure event detected',
        r'timeout': 'Timeout occurred',
        r'disconnect': 'Disconnection event',
        r'exception': 'Exception raised',
        r'critical': 'Critical fault detected',
    }

    detected_faults = {}

    if isinstance(log_content, (list, tuple)):
        # Plain text logs
        for line in log_content:
            for pattern, description in fault_patterns.items():
                if re.search(pattern, line, re.IGNORECASE):
                    detected_faults.setdefault(description, 0)
                    detected_faults[description] += 1
    elif isinstance(log_content, (dict, list)):
        # JSON logs - convert to string and search
        log_str = json.dumps(log_content)
        for pattern, description in fault_patterns.items():
            matches = re.findall(pattern, log_str, re.IGNORECASE)
            if matches:
                detected_faults[description] = len(matches)
    else:
        raise TypeError("Unsupported log content type")

    return detected_faults

def generate_report(detected_faults):
    """
    Generates a summary report from detected faults.
    """
    if not detected_faults:
        return "No faults detected in the log."

    report_lines = ["Fault Diagnosis Report:"]
    for fault, count in detected_faults.items():
        report_lines.append(f"- {fault}: {count} occurrence(s)")
    return "\n".join(report_lines)

def main(log_file_path):
    try:
        log_content = read_log_file(log_file_path)
        detected_faults = diagnose_faults(log_content)
        report = generate_report(detected_faults)
        print(report)
    except Exception as e:
        print(f"Error during diagnosis: {e}")

if __name__ == "__main__":
    import sys
    if len(sys.argv) != 2:
        print("Usage: python diagnose_faults.py <log_file_path>")
    else:
        main(sys.argv[1])
```

